function slvNorm(v){const s=((v||'')+'').toLowerCase();if(s==='partial'||s==='partially')return 'partially';if(s==='cannot')return 'cannot';if(s==='yes'||s==='no'||s==='-'||s==='?')return s;return v||'';}
function paintLabel(v){const s=((v||'')+'').toLowerCase();if(s==='fully')return 'fully painted';if(s==='partially'||s==='partial')return 'partially painted';if(s==='primed')return 'primed';if(s==='not')return 'not painted';return v;}
function paintColor(v){const s=((v||'')+'').toLowerCase();if(s==='fully')return '#6dbf7e';if(s==='partially'||s==='partial')return '#d4a843';if(s==='primed')return '#8aa0c0';if(s==='not')return '#e8614a';return '#857a62';}
function minisLine(g){const p=[];if(g.minis_s)p.push(g.minis_s+' S');if(g.minis_m)p.push(g.minis_m+' M');if(g.minis_l)p.push(g.minis_l+' L');let out=p.join(' · ');if(g.minis_detail)out=out?out+' — '+g.minis_detail:g.minis_detail;return out;}
